// don't load directly 
if (!defined('ABSPATH')) {
	header('Status: 403 Forbidden');
	header('HTTP/1.1 403 Forbidden');
	exit();
}

/**
 * Retrieve Settings Tabs  
 * Default sections by tab below 
 * @since       1.2.4
 * @return      array
 */
function wpematico_get_settings_sections() {
	$sections					  = array();
	$sections['general_settings'] = __('General', 'wpematico');
	$sections['advanced_actions'] = __('Advanced', 'wpematico');
	$sections['backend_tools']	  = __('Backend Tools', 'wpematico');

	return apply_filters('wpematico_settings_sections', $sections);
}

/**
 * Retrieve Settings Tabs  
 * Default sections by tab below 
 * @since       1.2.4
 * @return      array
 */
function wpematico_get_settings_tabs() {
	$tabs				  = array();
	$tabs['settings']	  = __('Settings', 'wpematico');
	//allways Licenses item at end
	$tabs				  = apply_filters('wpematico_settings_tabs', $tabs);
	$tabs['pro_licenses'] = __('Licenses', 'wpematico');

	return $tabs;
}

//Make Tabs calling actions and Sections if exist
function wpematico_settings_page_menu() {
	global $pagenow, $wp_roles, $current_user, $current_screen, $current_tab, $current_section, $tabs, $sections;
	$wpematico_icons = wpematico_settings_icons();
	?>
	<div class="wpematico_menu">
		<?php
		echo '<a class="wpematico_menu_close' . (($current_screen->id != 'wpematico_settings') ? " border-right" : "") . '" title="' . __('Hide/Show menu.', 'wpematico') . '" href="#"><span class="wpematico_link_icon">' . $wpematico_icons['icon_menu'] . '</span> <span class="wpematico_link_text">' . __('MENU', 'wpematico') . '</span></a>';
		foreach ($tabs as $tab_id => $tab_name) {
			$tab_url = add_query_arg(array(
				'tab' => $tab_id
			));

			$tab_url = remove_query_arg(array(
				'section'
					), $tab_url);

			$active					  = $current_tab == $tab_id ? 'menu-active' : '';
			$wpematico_icons[$tab_id] = $wpematico_icons[$tab_id] ?? $wpematico_icons['settings'];
			echo '<a href="' . esc_url($tab_url) . '" title="' . esc_attr(sanitize_text_field($tab_name)) . '" class="wpematico_menu_link ' . esc_attr($active) . '"><span class="wpematico_link_icon">' . $wpematico_icons[$tab_id] . '</span> <span class="wpematico_link_text">' . wp_kses_post($tab_name) . '</span></a>';
			$active === 'menu-active' && wpematico_print_tab_menu_sections();
		}
		?>
	</div><!-- .wpematico_menu -->
	<?php
}

function wpematico_print_tab_menu_sections() {
	global $pagenow, $wp_roles, $current_user, $current_screen, $current_tab, $current_section, $tabs, $sections;
	// Define the icons
	$default_icon  = '<svg xmlns="http://www.w3.org/2000/svg" fill="#000000" viewBox="0 0 24 24"><path d="M14 13H8V5H6v9a1 1 0 0 0 1 1h7v3l5-4-5-4v3z"/></svg>';
	$multiple_icon = '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" version="1.1" id="Capa_1" x="0px" y="0px" viewBox="0 0 800 800" style="enable-background:new 0 0 800 800;" xml:space="preserve"><path d="M616.7,400L616.7,400L450,533.3v-99.9H250V700h-66.7V401.4c0-0.5,0-1,0-1.4V100H250v266.7h200v-100L616.7,400z"/></svg>';

	$section_count = count($sections);
	$current_index = 0;
	?>	
	<div class="wpematico_menu_sections">
		<?php
		foreach ($sections as $section_id => $section_name) {
			$current_index++;
			$section_url = add_query_arg(array(
				'section' => $section_id
			));
			$active		 = $current_section == $section_id ? ' nav-section-active' : '';

			// Determine which icon to use
			$icon_to_use = $default_icon;
			if ($section_count > 1 && $current_index < $section_count) {
				$icon_to_use = $multiple_icon;
			}
			echo '<a href="' . esc_url($section_url) . '" title="' . esc_attr($section_name) . '" class="wpematico_submenu_link' . esc_attr($active) . '"><span class="wpematico_link_icon">' . $icon_to_use . '</span> <span class="wpematico_link_text">' . wp_kses_post($section_name) . '</span></a>';
		}
		?>
	</div><!-- .wpematico_menu_sections -->
	<?php
}

